SELECT ol.id, ol.doc_flag, ol.doc_title, ol.doc_keyword, ol.doc_desc,
ol.doc_context, ol.doc_app_context,
ol.star_level, ol.pub_flag, ol.create_user_id, ol.create_time, ol.update_user_id, ol.update_time, ol.scope_user_id, ol.scope_org_id, ol.tenant_id FROM doc_online ol LEFT JOIN doc_dir_rel rel ON ol.id = rel.doc_id
AND ol.doc_flag = #{pageDTO.docFlag}
AND rel.dir_id = #{pageDTO.docDirId}
AND ol.doc_title LIKE #{pageDTO.docTitle}
AND ol.doc_keyword LIKE #{pageDTO.docKeyword}
ORDER BY ol.create_time DESC

SELECT
    *
FROM
    doc_online
WHERE id = #{onlineId}
AND doc_flag = #{docFlag}

SELECT * FROM doc_online WHERE doc_flag = #{lastDTO.docFlag}
AND id < #{lastDTO.id} ORDER BY create_time DESC LIMIT 1
AND id > #{lastDTO.id} ORDER BY create_time ASC LIMIT 1
